    private async Task<ServiceResult<Guid>> UpsertRouteAsync(Guid actor,Guid? id,UpsertRouteRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);var entity=id??Guid.NewGuid();const string sql=@"insert into udrive.routes(id,name,origin_destination_id,destination_id,origin_location,destination_location,distance_km,estimated_minutes,recommended_vehicle,four_by_four_required,daylight_only,safety_score,is_active,created_at,updated_at) values(@id,@name,@origin,@destination,st_setsrid(st_makepoint(@olng,@olat),4326)::geography,st_setsrid(st_makepoint(@dlng,@dlat),4326)::geography,@distance,@minutes,@vehicle,@four,@day,@safety,@active,now(),now()) on conflict(id) do update set name=excluded.name,origin_destination_id=excluded.origin_destination_id,destination_id=excluded.destination_id,origin_location=excluded.origin_location,destination_location=excluded.destination_location,distance_km=excluded.distance_km,estimated_minutes=excluded.estimated_minutes,recommended_vehicle=excluded.recommended_vehicle,four_by_four_required=excluded.four_by_four_required,daylight_only=excluded.daylight_only,safety_score=excluded.safety_score,is_active=excluded.is_active,updated_at=now()";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",entity);cmd.Parameters.AddWithValue("name",request.Name);AddGuid(cmd,"origin",request.OriginDestinationId);AddGuid(cmd,"destination",request.DestinationId);cmd.Parameters.AddWithValue("olng",request.OriginLongitude);cmd.Parameters.AddWithValue("olat",request.OriginLatitude);cmd.Parameters.AddWithValue("dlng",request.DestinationLongitude);cmd.Parameters.AddWithValue("dlat",request.DestinationLatitude);cmd.Parameters.AddWithValue("distance",request.DistanceKm);cmd.Parameters.AddWithValue("minutes",request.EstimatedMinutes);cmd.Parameters.AddWithValue("vehicle",request.RecommendedVehicle);cmd.Parameters.AddWithValue("four",request.FourByFourRequired);cmd.Parameters.AddWithValue("day",request.DaylightOnly);cmd.Parameters.AddWithValue("safety",request.SafetyScore);cmd.Parameters.AddWithValue("active",request.IsActive);await cmd.ExecuteNonQueryAsync(ct);await AuditStandaloneAsync(cn,actor,id is null?"route.created":"route.updated","Route",entity.ToString(),JsonSerializer.Serialize(request),ct);return id is null?ServiceResult<Guid>.Created(entity):ServiceResult<Guid>.Ok(entity);}

    public async Task<ServiceResult<IReadOnlyList<AdminAdvisoryDto>>> AdvisoriesAsync(CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);const string sql=@"select a.id,a.route_id,r.name,a.severity,a.title_en,a.title_ur,a.details_en,a.details_ur,a.source_name,a.starts_at,a.ends_at,a.is_active from udrive.route_advisories a left join udrive.routes r on r.id=a.route_id order by a.created_at desc";var list=new List<AdminAdvisoryDto>();await using var cmd=new NpgsqlCommand(sql,cn);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.IsDBNull(1)?null:r.GetGuid(1),r.IsDBNull(2)?null:r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.GetFieldValue<DateTimeOffset>(9),r.IsDBNull(10)?null:r.GetFieldValue<DateTimeOffset>(10),r.GetBoolean(11)));return ServiceResult<IReadOnlyList<AdminAdvisoryDto>>.Ok(list);}
    public Task<ServiceResult<Guid>> CreateAdvisoryAsync(Guid actor,UpsertAdvisoryRequest request,CancellationToken ct)=>UpsertAdvisoryAsync(actor,null,request,ct);public Task<ServiceResult<Guid>> UpdateAdvisoryAsync(Guid actor,Guid id,UpsertAdvisoryRequest request,CancellationToken ct)=>UpsertAdvisoryAsync(actor,id,request,ct);
    private async Task<ServiceResult<Guid>> UpsertAdvisoryAsync(Guid actor,Guid? id,UpsertAdvisoryRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);var entity=id??Guid.NewGuid();const string sql=@"insert into udrive.route_advisories(id,route_id,severity,title_en,title_ur,details_en,details_ur,source_name,starts_at,ends_at,is_active,created_at,updated_at) values(@id,@route,@severity,@en,@ur,@den,@dur,@source,@starts,@ends,@active,now(),now()) on conflict(id) do update set route_id=excluded.route_id,severity=excluded.severity,title_en=excluded.title_en,title_ur=excluded.title_ur,details_en=excluded.details_en,details_ur=excluded.details_ur,source_name=excluded.source_name,starts_at=excluded.starts_at,ends_at=excluded.ends_at,is_active=excluded.is_active,updated_at=now()";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",entity);AddGuid(cmd,"route",request.RouteId);cmd.Parameters.AddWithValue("severity",request.Severity);cmd.Parameters.AddWithValue("en",request.TitleEn);cmd.Parameters.AddWithValue("ur",request.TitleUr);cmd.Parameters.AddWithValue("den",request.DetailsEn);cmd.Parameters.AddWithValue("dur",request.DetailsUr);cmd.Parameters.AddWithValue("source",request.SourceName);cmd.Parameters.AddWithValue("starts",request.StartsAt);AddDateTime(cmd,"ends",request.EndsAt);cmd.Parameters.AddWithValue("active",request.IsActive);await cmd.ExecuteNonQueryAsync(ct);await AuditStandaloneAsync(cn,actor,id is null?"advisory.created":"advisory.updated","RouteAdvisory",entity.ToString(),JsonSerializer.Serialize(request),ct);return id is null?ServiceResult<Guid>.Created(entity):ServiceResult<Guid>.Ok(entity);}

    public async Task<ServiceResult<IReadOnlyList<AdminSafetyIncidentDto>>> SafetyIncidentsAsync(CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);const string sql=@"select s.id,b.booking_reference,u.full_name,s.severity,s.incident_type,s.description,s.status,a.full_name,s.resolution_notes,s.created_at,s.resolved_at from udrive.safety_incidents s join udrive.users u on u.id=s.reported_by_user_id left join udrive.bookings b on b.id=s.booking_id left join udrive.users a on a.id=s.assigned_admin_user_id order by case s.severity when 'Critical' then 1 when 'High' then 2 else 3 end,s.created_at desc";var list=new List<AdminSafetyIncidentDto>();await using var cmd=new NpgsqlCommand(sql,cn);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.IsDBNull(1)?null:r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.GetFieldValue<DateTimeOffset>(9),r.IsDBNull(10)?null:r.GetFieldValue<DateTimeOffset>(10)));return ServiceResult<IReadOnlyList<AdminSafetyIncidentDto>>.Ok(list);}
    public async Task<ServiceResult<bool>> UpdateSafetyIncidentAsync(Guid actor,Guid id,UpdateSafetyIncidentRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);const string sql=@"update udrive.safety_incidents set status=@status,assigned_admin_user_id=@assigned,assigned_at=case when @assigned is null then assigned_at else coalesce(assigned_at,now()) end,resolution_notes=@notes,resolved_at=case when @status in ('Resolved','Closed') then now() else null end,updated_at=now() where id=@id";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("status",request.Status);AddGuid(cmd,"assigned",request.AssignedAdminUserId);AddText(cmd,"notes",request.ResolutionNotes);if(await cmd.ExecuteNonQueryAsync(ct)==0)return ServiceResult<bool>.Fail(404,"incident_not_found","Safety incident not found.");await AuditStandaloneAsync(cn,actor,"safety.updated","SafetyIncident",id.ToString(),JsonSerializer.Serialize(request),ct);return ServiceResult<bool>.Ok(true);}

