    public async Task<ServiceResult<Guid>> CreateTicketAsync(Guid actor,CreateSupportTicketRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);var id=Guid.NewGuid();var reference=$"SUP-{DateTime.UtcNow:yyMMdd}-{Random.Shared.Next(1000,9999)}";const string sql=@"insert into udrive.support_tickets(id,reference,created_by_user_id,booking_id,category,priority,subject,description,status,created_at,updated_at) values(@id,@ref,@customer,@booking,@category,@priority,@subject,@description,'Open',now(),now())";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("ref",reference);AddGuid(cmd,"customer",request.CustomerUserId);AddGuid(cmd,"booking",request.BookingId);cmd.Parameters.AddWithValue("category",request.Category);cmd.Parameters.AddWithValue("priority",request.Priority);cmd.Parameters.AddWithValue("subject",request.Subject);cmd.Parameters.AddWithValue("description",request.Description);await cmd.ExecuteNonQueryAsync(ct);await AuditStandaloneAsync(cn,actor,"support.created","SupportTicket",id.ToString(),JsonSerializer.Serialize(request),ct);return ServiceResult<Guid>.Created(id,reference);}
