    public async Task<ServiceResult<int>> BroadcastAsync(Guid actor,BroadcastNotificationRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);const string sql=@"insert into udrive.notifications(id,user_id,type,title,body,data_json,created_at,updated_at) select gen_random_uuid(),u.id,@type,@title,@body,cast(@data as jsonb),now(),now() from udrive.users u where (@role is null or exists(select 1 from udrive.user_roles ur where ur.user_id=u.id and ur.role=@role))";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("type",request.Type);cmd.Parameters.AddWithValue("title",request.Title);cmd.Parameters.AddWithValue("body",request.Body);AddText(cmd,"role",request.AudienceRole);cmd.Parameters.AddWithValue("data",request.Data?.GetRawText()??"{}");var count=await cmd.ExecuteNonQueryAsync(ct);await AuditStandaloneAsync(cn,actor,"notification.broadcast","Notification","broadcast",JsonSerializer.Serialize(new{request.Type,request.Title,request.AudienceRole,count}),ct);return ServiceResult<int>.Created(count,$"Notification queued for {count} users.");}

