    public async Task<ServiceResult<int>> UpdateSettingsAsync(Guid actor,UpdateSettingsRequest request,CancellationToken ct){await using var cn=OpenConnection();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);var count=0;foreach(var item in request.Values){await using var cmd=new NpgsqlCommand("insert into udrive.system_settings(key,value_json,updated_by_user_id,created_at,updated_at) values(@key,cast(@value as jsonb),@actor,now(),now()) on conflict(key) do update set value_json=excluded.value_json,updated_by_user_id=excluded.updated_by_user_id,updated_at=now()",cn,tx);cmd.Parameters.AddWithValue("key",item.Key);cmd.Parameters.AddWithValue("value",item.Value.GetRawText());cmd.Parameters.AddWithValue("actor",actor);count+=await cmd.ExecuteNonQueryAsync(ct);}await AuditAsync(cn,tx,actor,"settings.updated","SystemSettings","multiple",JsonSerializer.Serialize(request.Values.Keys),ct);await tx.CommitAsync(ct);return ServiceResult<int>.Ok(count);}

    private static AdminBookingListItemDto MapBooking(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.GetString(6),r.GetString(7),r.GetInt32(8),r.GetDecimal(9),r.GetDecimal(10),r.GetDecimal(11),r.IsDBNull(12)?null:r.GetString(12),r.IsDBNull(13)?null:r.GetString(13),r.GetFieldValue<DateTimeOffset>(14),r.GetFieldValue<DateTimeOffset>(15));
    private async Task<AdminBookingListItemDto?> BookingsByIdAsync(NpgsqlConnection cn,Guid id,CancellationToken ct){const string sql=@"select b.id,b.booking_reference,u.full_name,u.phone_number,du.full_name,case when v.id is null then null else concat(v.make,' ',v.model,' · ',v.registration_number) end,b.booking_type,b.status,b.seats_booked,b.total_amount,b.advance_amount,b.remaining_amount,b.pickup_label,b.destination_label,b.pickup_at,b.created_at from udrive.bookings b join udrive.users u on u.id=b.customer_user_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id where b.id=@id";await using var cmd=new NpgsqlCommand(sql,cn);cmd.Parameters.AddWithValue("id",id);await using var r=await cmd.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?MapBooking(r):null;}
