    private static async Task<int> ScalarIntAsync(NpgsqlConnection cn,string sql,CancellationToken ct){await using var cmd=new NpgsqlCommand(sql,cn);return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)??0);}
    private static async Task<Dictionary<string,int>> CountByAsync(NpgsqlConnection cn,string sql,CancellationToken ct){var d=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);await using var cmd=new NpgsqlCommand(sql,cn);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))d[r.GetString(0)]=Convert.ToInt32(r.GetInt64(1));return d;}
    private static void AddText(NpgsqlCommand cmd,string name,string? value)=>cmd.Parameters.Add(new NpgsqlParameter(name,NpgsqlDbType.Text){Value=(object?)value??DBNull.Value});
    private static void AddGuid(NpgsqlCommand cmd,string name,Guid? value)=>cmd.Parameters.Add(new NpgsqlParameter(name,NpgsqlDbType.Uuid){Value=value.HasValue?(object)value.Value:DBNull.Value});
    private static void AddDateTime(NpgsqlCommand cmd,string name,DateTimeOffset? value)=>cmd.Parameters.Add(new NpgsqlParameter(name,NpgsqlDbType.TimestampTz){Value=value.HasValue?(object)value.Value:DBNull.Value});
    private static async Task AuditStandaloneAsync(NpgsqlConnection cn,Guid actor,string action,string type,string entity,string changes,CancellationToken ct){await using var cmd=new NpgsqlCommand("insert into udrive.audit_logs(id,actor_user_id,action,entity_type,entity_id,changes_json,created_at,updated_at) values(gen_random_uuid(),@actor,@action,@type,@entity,cast(@changes as jsonb),now(),now())",cn);cmd.Parameters.AddWithValue("actor",actor);cmd.Parameters.AddWithValue("action",action);cmd.Parameters.AddWithValue("type",type);cmd.Parameters.AddWithValue("entity",entity);cmd.Parameters.AddWithValue("changes",changes);await cmd.ExecuteNonQueryAsync(ct);}
    private static async Task AuditAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid actor,string action,string type,string entity,string changes,CancellationToken ct){await using var cmd=new NpgsqlCommand("insert into udrive.audit_logs(id,actor_user_id,action,entity_type,entity_id,changes_json,created_at,updated_at) values(gen_random_uuid(),@actor,@action,@type,@entity,cast(@changes as jsonb),now(),now())",cn,tx);cmd.Parameters.AddWithValue("actor",actor);cmd.Parameters.AddWithValue("action",action);cmd.Parameters.AddWithValue("type",type);cmd.Parameters.AddWithValue("entity",entity);cmd.Parameters.AddWithValue("changes",changes);await cmd.ExecuteNonQueryAsync(ct);}
